      chips.forEach((chip) => {
        chip.addEventListener("click", () => {
          const filter = chip.dataset.filter;

          chips.forEach((item) => item.setAttribute("aria-pressed", String(item === chip)));

          products.forEach((product) => {
            const match = filter === "all" || product.dataset.category === filter;
            product.style.display = match ? "" : "none";
          });
        });
      });

      const countdown = [
        document.getElementById("hours"),
        document.getElementById("minutes"),
        document.getElementById("seconds"),
      ];

      let remaining = 12 * 3600 + 24 * 60 + 55;

      setInterval(() => {
        remaining = Math.max(0, remaining - 1);
        const hours = Math.floor(remaining / 3600);
        const minutes = Math.floor((remaining % 3600) / 60);
        const seconds = remaining % 60;

        countdown[0].textContent = String(hours).padStart(2, "0");
        countdown[1].textContent = String(minutes).padStart(2, "0");
        countdown[2].textContent = String(seconds).padStart(2, "0");
      }, 1000);
