    />
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b0d12;
        --panel: #121621;
        --panel-2: #171c28;
        --text: #f5f7fb;
        --muted: #a8b0c3;
        --line: rgba(255, 255, 255, 0.08);
        --accent: #8b5cf6;
        --accent-2: #22c55e;
        --warm: #f59e0b;
        --shadow: 0 18px 60px rgba(0, 0, 0, 0.45);
        --radius: 22px;
        --radius-sm: 16px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(139, 92, 246, 0.16), transparent 30%),
          radial-gradient(circle at 85% 15%, rgba(34, 197, 94, 0.1), transparent 20%),
          var(--bg);
        color: var(--text);
      }

      a {
        color: inherit;
        text-decoration: none;
      }

      button,
      input {
        font: inherit;
      }

      button,
      a,
      input {
        transition: transform 140ms ease, border-color 140ms ease, background-color 140ms ease, color 140ms ease;
      }

      :focus-visible {
        outline: 2px solid rgba(139, 92, 246, 0.95);
        outline-offset: 3px;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      .skip-link {
        position: absolute;
        left: -999px;
        top: 1rem;
        background: var(--text);
        color: var(--bg);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        z-index: 10;
      }

      .skip-link:focus {
        left: 1rem;
      }

      .shell {
        width: min(1180px, calc(100% - 2rem));
        margin: 0 auto;
      }

      .topbar {
        position: sticky;
        top: 0;
        z-index: 20;
        backdrop-filter: blur(18px);
        background: rgba(11, 13, 18, 0.75);
        border-bottom: 1px solid var(--line);
      }

      .topbar-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      .brand-mark {
        width: 2.3rem;
        height: 2.3rem;
        border-radius: 0.8rem;
        background: linear-gradient(135deg, var(--accent), #ec4899);
        box-shadow: 0 10px 25px rgba(139, 92, 246, 0.35);
      }

      .nav {
        display: flex;
        gap: 1rem;
        flex-wrap: wrap;
        justify-content: center;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .nav a:hover,
      .nav a:focus-visible {
        color: var(--text);
      }

      .actions {
        display: flex;
        align-items: center;
        gap: 0.75rem;
      }

      .icon-btn,
      .chip,
      .cta,
      .ghost {
        border: 1px solid var(--line);
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.03);
        color: var(--text);
        cursor: pointer;
      }

      .icon-btn {
        width: 2.75rem;
        height: 2.75rem;
      }

      .hero {
        padding: 3.2rem 0 2rem;
      }

      .hero-grid {
        display: grid;
        grid-template-columns: 1.2fr 0.8fr;
        gap: 1.25rem;
        align-items: stretch;
      }

      .card {
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.02));
        border: 1px solid var(--line);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
      }

      .hero-main {
        padding: 2rem;
        min-height: 32rem;
        display: grid;
        gap: 1.5rem;
        align-content: space-between;
        overflow: hidden;
        position: relative;
      }

      .eyebrow {
        display: inline-flex;
        gap: 0.5rem;
        align-items: center;
