        line-height: 1.7;
      }

      .hero-cta {
        display: flex;
        gap: 0.8rem;
        flex-wrap: wrap;
      }

      .cta,
      .ghost {
        padding: 0.95rem 1.3rem;
        font-weight: 600;
      }

      .cta {
        background: linear-gradient(135deg, var(--accent), #6d28d9);
        border-color: transparent;
        box-shadow: 0 15px 30px rgba(139, 92, 246, 0.22);
      }

      .ghost:hover,
      .cta:hover,
      .chip:hover,
      .icon-btn:hover {
        transform: translateY(-1px);
