        .topbar-inner {
          flex-direction: column;
          align-items: start;
        }

        .nav {
          justify-content: start;
        }

        .hero {
          padding-top: 1.6rem;
        }

        .hero-main,
        .stat-panel,
        .deal-panel,
        .deal-feature,
        .story {
          padding: 1.1rem;
        }

        .hero-grid,
        .deal-section,
        .story-grid,
        .product-grid {
          grid-template-columns: 1fr;
        }

        .stat-grid {
          grid-template-columns: 1fr;
        }

        .deal-timer {
          grid-template-columns: repeat(2, 1fr);
        }
      }
    </style>
  </head>
